#!/usr/bin/env bash
# EBATKART_TASMA_V1 deploy — Ebat Kartı yatay taşma düzeltmesi (mobil). Rule 5. Idempotent.
set -e
cd /opt/krb-assessment
if [ -f shells/saha.js ]; then SAHA=shells/saha.js; else SAHA=$(find . -maxdepth 3 -name saha.js -not -path '*/backups/*' -not -path '*/node_modules/*'|head -1); fi
[ -f "$SAHA" ] || { echo "HATA: saha.js yok"; exit 1; }
cp "$SAHA" "$SAHA.bak.$(date +%s)"
printf '%s' '' | base64 -d > /tmp/ebatkart_fix.py
SDIR=$(dirname "$SAHA"); cp /tmp/ebatkart_fix.py "$SDIR/ebatkart_fix.py"
( cd "$SDIR" && python3 ebatkart_fix.py ) && rm -f "$SDIR/ebatkart_fix.py"
node --check "$SAHA" && echo SAHA_OK
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 4
docker exec krb-assessment sh -c "grep -c EBATKART_TASMA_V1 /app/shells/saha.js" || true
echo "== DONE =="
